{
  "contradictions": [
    {
      "a_quote": "I was in Mercer County playing cards with friends from 20:30 until 01:15 and never drove anywhere near Apex Auto Body & Paint on 2019-04-11.",
      "a_doc": "doc07",
      "b_quote": "2019-04-11 23:02 — State Route 41 Gantry Southbound (toward Apex Auto Body & Paint), plate RGZ-9535 (charcoal 2015 Nissan Altima, reg. Estelle Burnett).",
      "b_doc": "doc09",
      "kind": "alibi_vs_record",
      "severity": "high",
      "innocent_alternative": "Estelle Burnett later acknowledged in doc08 concealing his brief 23:02–23:14 lot visit out of concern over his ongoing legal dispute, while doc09 and doc10 corroborate his departure prior to 23:52."
    },
    {
      "a_quote": "I clocked out at 22:15, called goodnight to Julian Caffrey through the closed estimator glass office door while Julian worked inside, and drove straight home before 22:50.",
      "a_doc": "doc12",
      "b_quote": "I left around 22:00, maybe ten past, and I stopped by the supply alcove where Julian Caffrey stepped out of the estimator glass office to talk for a minute about Tuesday's schedule before I headed home.",
      "b_doc": "doc13",
      "kind": "statement_drift",
      "severity": "medium",
      "innocent_alternative": "Ordinary episodic memory decay and telescoping across the 6-year gap between initial and cold-case interviews."
    }
  ],
  "alibis": [
    {
      "person": "Sylvia Quintana",
      "window": "Narrowed survival window 23:52–00:36 (within ME window 22:36–00:36)",
      "rating": "uncorroborated",
      "reasons": [
        {
          "quote": "I never entered the estimator glass office at any point that night. On my rounds I only check the exterior handle from the corridor.",
          "doc_id": "doc03"
        },
        {
          "quote": "00:13 — Checked estimator glass office door from corridor, handle secure.",
          "doc_id": "doc04"
        },
        {
          "quote": "2019-04-11 23:18 — FAULT 0x04: local CMOS backup battery depleted; events from 23:18 through 06:56 unbuffered locally. Raw serial audit tape spooled to off-site alarm vendor archive reel #AR-134, not yet pulled.",
          "doc_id": "doc05"
        },
        {
          "quote": "Digital billing server retained monthly gross kWh totals only; 15-minute sub-circuit demand strip-chart roll for 2019-04-11–2019-04-12 is stored in unindexed utility microfilm Box #UF-344 and has not yet been pulled.",
          "doc_id": "doc11"
        }
      ]
    },
    {
      "person": "Estelle Burnett",
      "window": "Narrowed survival window 23:52–00:36 (within ME window 22:36–00:36)",
      "rating": "corroborated",
      "reasons": [
        {
          "quote": "2019-04-11 23:24 — State Route 41 Gantry Northbound (away from Apex Auto Body & Paint into Mercer County), plate RGZ-9535.",
          "doc_id": "doc09"
        },
        {
          "quote": "2019-04-11 23:42 — Mercer County Co-op Cardlock Pump #3 (16.2 road miles north of Apex Auto Body & Paint), PIN-verified fuel purchase on card of Estelle Burnett, plate RGZ-9535 captured on pump camera; zero southbound gantry hits thereafter through 06:00.",
          "doc_id": "doc09"
        },
        {
          "quote": "2019-04-11 23:52 — Outgoing SMS from Julian Caffrey's handset (recovered in estimator glass office) to sibling: \"still closing out the ledger in the office alone, locking up in twenty minutes.\"",
          "doc_id": "doc10"
        },
        {
          "quote": "After reviewing the toll record, I admit I drove my charcoal 2015 Nissan Altima to the Apex Auto Body & Paint lot around 23:02 to discuss our financial dispute. The estimator glass office window looked dark behind the blinds, nobody answered, so I pulled out by 23:14, crossed State Route 41 back into Mercer County, and fueled at the cardlock pump at 23:42.",
          "doc_id": "doc08"
        }
      ]
    },
    {
      "person": "Gregory Vogel",
      "window": "Narrowed survival window 23:52–00:36 (within ME window 22:36–00:36)",
      "rating": "uncorroborated",
      "reasons": [
        {
          "quote": "I clocked out at 22:15, called goodnight to Julian Caffrey through the closed estimator glass office door while Julian worked inside, and drove straight home before 22:50.",
          "doc_id": "doc12"
        },
        {
          "quote": "I left around 22:00, maybe ten past, and I stopped by the supply alcove where Julian Caffrey stepped out of the estimator glass office to talk for a minute about Tuesday's schedule before I headed home.",
          "doc_id": "doc13"
        },
        {
          "quote": "During the 2025-08-06 cold-case canvas, Lucia Vogel stated for the first time that Gregory Vogel arrived home prior to 23:00 on 2019-04-11.",
          "doc_id": "doc14"
        }
      ]
    },
    {
      "person": "Mitchell Delgado",
      "window": "Narrowed survival window 23:52–00:36 (within ME window 22:36–00:36)",
      "rating": "uncorroborated",
      "reasons": [
        {
          "quote": "I returned to Apex Auto Body & Paint around 22:54 and keyed my own PIN 6763 at the estimator glass office door to pick up my keys. Julian Caffrey was seated at the desk alive doing end-of-shift reconciliation. I stayed two minutes and drove straight home by 23:25.",
          "doc_id": "doc06"
        },
        {
          "quote": "2019-04-11 22:54 — PIN 6763 UNLOCK",
          "doc_id": "doc05"
        }
      ]
    }
  ],
  "evidence_gaps": [
    {
      "item": "Off-site alarm vendor serial audit backup reel & utility sub-meter microfilm",
      "mentioned_in": [
        "doc05",
        "doc11"
      ],
      "problem": "Local keypad CMOS battery failed at 23:18 and utility digital billing omitted interval data; archival backups were never pulled."
    },
    {
      "item": "Second spent 9mm Luger brass shell casings at marker 5",
      "mentioned_in": [
        "doc01",
        "doc15"
